-- Verify 20 Nov 2026 Claude quote fix. Read-only. Does not pin the tools count.
SELECT 'row' AS k, domain, compliance_status, trains_on_user_data, manual_override, last_checked_at, source_urls, summary, data_retention FROM tools WHERE domain='claude.com';
SELECT 'scope' AS k, COUNT(*) AS n FROM tools WHERE last_checked_at='2026-11-18T11:20:00.000Z';
SELECT CASE WHEN (SELECT COUNT(*) FROM tools WHERE last_checked_at='2026-11-18T11:20:00.000Z')=1 THEN 'ok: exactly 1 row in this batch' ELSE json('VERIFY FAILED: batch scope') END AS verify_scope;
SELECT CASE WHEN (SELECT COUNT(*) FROM tools WHERE domain='claude.com' AND compliance_status='compliant_with_caveats' AND trains_on_user_data=1 AND manual_override=1 AND last_checked_at='2026-11-18T11:20:00.000Z' AND summary='We may use your Inputs and Outputs to train and improve Anthropic AI models, unless you opt out through your account settings. This Privacy Policy does not apply to content that we process on behalf of customers of our business offerings, such as our Enterprise accounts.' AND data_retention='You also are able to delete individual conversations, which will be removed immediately from your conversation history and automatically deleted from our back-end within 30 days.' AND source_urls='["https://www.anthropic.com/legal/privacy", "https://www.anthropic.com/legal/commercial-terms"]')=1 THEN 'ok: claude.com' ELSE json('VERIFY FAILED: claude.com') END AS verify_row;
SELECT 'counts_by_status' AS k, compliance_status, COUNT(*) AS n FROM tools GROUP BY compliance_status ORDER BY compliance_status;
